def clean_old_data(apps, schema_editor):
    """Turn old free-text quantities like "5 bags" into numbers and copy is_contacted into status."""
    import re
    Enquiry = apps.get_model("enquiries", "Enquiry")
    for e in Enquiry.objects.all():
        digits = re.findall(r"\d+", str(e.quantity or ""))
        e.quantity = digits[0] if digits else None
        if e.is_contacted:
            e.status = "contacted"
        e.save(update_fields=["quantity", "status"])


